1	package main
2	
3	import (
4		"encoding/json"
5		"flag"
6		"os"
7		"path/filepath"
8		"reflect"
9		"strconv"
10		"strings"
11	
12		"github.com/GopeedLab/gopeed/pkg/base"
13	)
14	
15	type args struct {
16		TempDir           *string  `json:"tempDir"`
17		Address           *string  `json:"address"`
18		Port              *int     `json:"port"`
19		Username          *string  `json:"username"`
20		Password          *string  `json:"password"`
21		ApiToken          *string  `json:"apiToken"`
22		MCPEnable         bool     `json:"mcpEnable"`
23		StorageDir        *string  `json:"storageDir"`
24		WhiteDownloadDirs []string `json:"whiteDownloadDirs"`
25		// DownloadConfig when the first time to start the server, it will be configured as initial value
26		DownloadConfig *base.DownloaderStoreConfig `json:"downloadConfig"`
27	
28		configPath *string
29	}
30	
31	func parse() *args {
32		cfg := &args{}
33	
34		cliConfig := loadCliArgs()
35		loadConfigFile(cfg, *cliConfig.configPath)
36		loadEnvVars(cfg)
37		// override with non-default command line arguments
38		overrideWithCliArgs(cfg, cliConfig)
39		// set default values
40		setDefaults(cfg, cliConfig)
41		return cfg
42	}
43	
44	// loadCliArgs parses command line arguments and returns initial config
45	func loadCliArgs() *args {
46		cfg := &args{}
47		cfg.Address = flag.String("A", "0.0.0.0", "Bind Address")
48		flag.StringVar(cfg.Address, "address", "0.0.0.0", "Bind Address")
49		cfg.Port = flag.Int("P", 9999, "Bind Port")
50		flag.IntVar(cfg.Port, "port", 9999, "Bind Port")
51		cfg.Username = flag.String("u", "gopeed", "Web Authentication Username")
52		flag.StringVar(cfg.Username, "username", "gopeed", "Web Authentication Username")
53		cfg.Password = flag.String("p", "", "Web Authentication Password, if no password is set, web authentication will not be enabled")
54		flag.StringVar(cfg.Password, "password", "", "Web Authentication Password, if no password is set, web authentication will not be enabled")
55		cfg.ApiToken = flag.String("T", "", "API token (requires web authentication with username and password)")
56		flag.StringVar(cfg.ApiToken, "api-token", "", "API token (requires web authentication with username and password)")
57		flag.BoolVar(&cfg.MCPEnable, "mcp-enable", false, "Enable MCP endpoint")
58		cfg.TempDir = flag.String("temp-dir", "", "Temporary directory (defaults to the OS temporary directory)")
59		cfg.StorageDir = flag.String("d", "", "Storage directory")
60		flag.StringVar(cfg.StorageDir, "storage-dir", "", "Storage directory")
61		whiteDownloadDirs := flag.String("white-download-dirs", "", "White download directories, comma-separated")
62		cfg.configPath = flag.String("c", "./config.json", "Config file path")
63		flag.StringVar(cfg.configPath, "config", "./config.json", "Config file path")
64		flag.Parse()
65	
66		// Parse white download directories from comma-separated string
67		if whiteDownloadDirs != nil && *whiteDownloadDirs != "" {
68			dirs := strings.Split(*whiteDownloadDirs, ",")
69			for i := range dirs {
70				dirs[i] = strings.TrimSpace(dirs[i])
71			}
72			cfg.WhiteDownloadDirs = dirs
73		}
74	
75		return cfg
76	}
77	
78	// overrideWithCliArgs overrides config with non-empty command line arguments
79	func overrideWithCliArgs(cfg *args, cliConfig *args) {
80		flag.Visit(func(f *flag.Flag) {
81			switch f.Name {
82			case "A", "address":
83				cfg.Address = cliConfig.Address
84			case "P", "port":
85				cfg.Port = cliConfig.Port
86			case "u", "username":
87				cfg.Username = cliConfig.Username
88			case "p", "password":
89				cfg.Password = cliConfig.Password
90			case "T", "api-token":
91				cfg.ApiToken = cliConfig.ApiToken
92			case "mcp-enable":
93				cfg.MCPEnable = cliConfig.MCPEnable
94			case "temp-dir":
95				cfg.TempDir = cliConfig.TempDir
96			case "d", "storage-dir":
97				cfg.StorageDir = cliConfig.StorageDir
98			case "white-download-dirs":
99				cfg.WhiteDownloadDirs = cliConfig.WhiteDownloadDirs
100			case "c", "config":
101				cfg.configPath = cliConfig.configPath
102			}
103		})
104	}
105	
106	// setDefaults sets default values for any unset configuration fields
107	func setDefaults(cfg *args, cliConfig *args) {
108		if cfg.TempDir == nil {
109			cfg.TempDir = cliConfig.TempDir
110		}
111		if cfg.Address == nil {
112			cfg.Address = cliConfig.Address
113		}
114		if cfg.Port == nil {
115			cfg.Port = cliConfig.Port
116		}
117		if cfg.Username == nil {
118			cfg.Username = cliConfig.Username
119		}
120		if cfg.Password == nil {
121			cfg.Password = cliConfig.Password
122		}
123		if cfg.ApiToken == nil {
124			cfg.ApiToken = cliConfig.ApiToken
125		}
126		if cfg.StorageDir == nil {
127			cfg.StorageDir = cliConfig.StorageDir
128		}
129	}
130	
131	// loadConfigFile loads configuration from file
132	func loadConfigFile(cfg *args, configPath string) {
133		if !filepath.IsAbs(configPath) {
134			dir, err := os.Getwd()
135			if err != nil {
136				return
137			}
138			configPath = filepath.Join(dir, configPath)
139		}
140	
141		file, err := os.ReadFile(configPath)
142		if err != nil {
143			if os.IsNotExist(err) {
144				return
145			}
146			return
147		}
148	
149		if err = json.Unmarshal(file, cfg); err != nil {
150			return
151		}
152	}
153	
154	// loadEnvVars loads configuration from environment variables with prefix GOPEED_
155	func loadEnvVars(cfg *args) {
156		v := reflect.ValueOf(cfg).Elem()
157		t := reflect.TypeOf(cfg).Elem()
158	
159		for i := 0; i < v.NumField(); i++ {
160			field := v.Field(i)
161			fieldType := t.Field(i)
162	
163			// Get json tag as environment variable suffix
164			jsonTag := fieldType.Tag.Get("json")
165			if jsonTag == "" || jsonTag == "-" {
166				continue
167			}
168	
169			// Remove options like omitempty
170			if commaIdx := strings.Index(jsonTag, ","); commaIdx != -1 {
171				jsonTag = jsonTag[:commaIdx]
172			}
173	
174			// Convert to uppercase and add GOPEED_ prefix
175			envKey := "GOPEED_" + strings.ToUpper(jsonTag)
176			envValue := os.Getenv(envKey)
177	
178			if envValue == "" {
179				continue
180			}
181	
182			// Set value based on field type
183			if field.Kind() == reflect.Ptr {
184				if field.IsNil() {
185					// Create new pointer instance
186					newVal := reflect.New(field.Type().Elem())
187					field.Set(newVal)
188				}
189	
190				switch field.Type().Elem().Kind() {
191				case reflect.String:
192					field.Elem().SetString(envValue)
193				case reflect.Int:
194					if intVal, err := strconv.Atoi(envValue); err == nil {
195						field.Elem().SetInt(int64(intVal))
196					}
